    tax = tax or DEFAULT_TAX

    cart_lines = cart.lines
    discounts = [ZERO] * len(cart_lines)
    if promo is not None:
        discounts = _promo_discounts(cart_lines, promo)
    discount_total = sum_money(discounts)

    lines: list[LineTotal] = []
    for cart_line, discount in zip(cart_lines, discounts):
